function ajouterArticle(panier, article) {
  panier.articles.push(article);
  return panier;
}

const avant = { articles: [] };
const apres = ajouterArticle(avant, "pomme");
console.log(avant === apres); // true

function ajouterArticle(panier, article) {
  return {
    ___panier,
    articles: [___panier.articles, article],
  };
}

